import { getAssetForApp, getAppKeyFromHost } from '../lib/ecosystem.js';

const BrandLogo = ({ appKey, label, className = '', size = 40 }) => {
  const resolvedKey =
    appKey || getAppKeyFromHost(typeof window === 'undefined' ? '' : window.location.hostname);
  const logoSrc = getAssetForApp(resolvedKey, 'logo');
  const fallbackLabel = label || resolvedKey || 'Vegvisr';

  if (!logoSrc) {
    return (
      <div className={`text-sm font-semibold uppercase tracking-[0.4em] text-white/60 ${className}`.trim()}>
        {fallbackLabel}
      </div>
    );
  }

  return (
    <img
      src={logoSrc}
      alt={fallbackLabel}
      className={className}
      style={{ height: size, width: 'auto' }}
    />
  );
};

export default BrandLogo;
